#include <windows.h>
#include <iostream>
#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_render_root_candidate.h"
#include "session_frame_rate_candidate.h"
#include "win32_vulkan_playback_candidate.h"
int main(){try{auto graph=loadGraph("work/movie-640x480-session.dmx");size_t edits=0;for(auto&attribute:graph.elements.at(2232).attributes)if(graph.strings.at(attribute.name)=="frameRate"){float fps=24;uint32_t bits;std::memcpy(&bits,&fps,4);setWireU32(attribute.values.at(0),bits);++edits;}auto root=sessionRenderRootCandidate(graph);auto rate24=sessionFrameRateCandidate(graph,root,false);auto rate60=recoveredFloatRateCandidate(60);if(edits!=1||rate24!=recoveredFloatRateCandidate(24))throw std::runtime_error("rate fixture coverage");saveGraph(graph,"work/movie-640x480-24fps-session.dmx");vulkanPlaybackState.test=true;vulkanPlaybackState.playing=true;vulkanPlaybackState.selected=7;vulkanPlaybackState.activeRate=rate60;vulkanPlaybackState.clock.setPackedRate(rate60);updatePresentedSceneRateCandidate(rate24);auto anchor=vulkanPlaybackState.clock.anchor;if(vulkanPlaybackState.clock.sample(anchor,1000)!=7||vulkanPlaybackState.clock.sample(anchor+1000000000,1000)!=31||!vulkanPlaybackState.playing)throw std::runtime_error("reload rate anchor/cadence");vulkanPlaybackState.clock.anchor=42;updatePresentedSceneRateCandidate(rate24);if(vulkanPlaybackState.clock.anchor!=42)throw std::runtime_error("same rate reset anchor");updatePresentedSceneRateCandidate(rate60);anchor=vulkanPlaybackState.clock.anchor;if(vulkanPlaybackState.clock.sample(anchor+1000000000,1000)!=67)throw std::runtime_error("restore rate cadence");vulkanPlaybackState.rateOverride=true;vulkanPlaybackState.clock.anchor=42;updatePresentedSceneRateCandidate(rate24);if(vulkanPlaybackState.activeRate!=rate60||vulkanPlaybackState.clock.anchor!=42)throw std::runtime_error("saved rate overwrote explicit clock");std::cout<<"reload playback rate passed rates=60,24,60 selected_frame_preserved=1 same_rate_anchor_unchanged=1 playing_state_preserved=1 explicit_override_preserved=1\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
